async function getPasskey(){const e=await(await fetch("/api/passkey/generator")).json();if(console.log(e),e.status==200&&(document.getElementById("passkey_accoun").innerHTML=e.message),e.status==500&&(document.getElementById("passkey_accoun").innerHTML=e.message),e.status==201){document.getElementById("passkey_accoun").innerHTML=e.message,document.getElementById("main_auth").innerHTML=`
        
        <div class="flex items-center justify-center md:mx-auto">
            <div class="w-full md:w-1/2 p-4 md:p-6">
                <div class="bg-white rounded-lg shadow-md p-4 md:p-6">
                    <div class="flex items-center justify-center mb-4 md:mb-6">
                        <div id="qrcodeUser" class="w-full md:w-1/2"></div>
                    </div>
                    <form class="w-full" id="ativate_passkey">
                        <input type="hidden" id="base32" name="base32" value="${e.data.base32}" />
                        <div class="mb-4 md:mb-6">
                            <label for="otp" class="block text-sm font-semibold text-gray-700 mb-2">Masukan OTP</label>
                            <input type="number" id="otp" name="otp" placeholder="Masukan OTP" required class="w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-green-500 focus:border-transparent bg-white text-gray-900" />
                        </div>
                        <div class="flex items-center justify-center">
                            <button type="submit" id="fsubmit" class="w-full md:w-auto bg-green-600 hover:bg-green-700 text-white font-semibold py-3 md:py-2 px-6 rounded-lg transition-colors duration-200">
                                Submit
                            </button>
                        </div>
                    </form>
                </div>
            </div>
        </div>
        `;const d=new QRCode("qrcodeUser",{text:e.data.otpauth_url,width:200,height:200,colorDark:"#000000",colorLight:"#ffffff",correctLevel:QRCode.CorrectLevel.H});document.getElementById("ativate_passkey").addEventListener("submit",async a=>{a.preventDefault();const s=document.getElementById("base32").value,n=document.getElementById("otp").value;console.log("Submit intercepted:",{base32:s,otp:n});const t=await(await fetch("/api/passkey/activate",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({base32:s,otp:n})})).json();t.status==401&&(document.getElementById("passkey_accoun").innerHTML=t.message),t.status==500&&(document.getElementById("passkey_accoun").innerHTML=t.message),t.status==201&&(document.getElementById("passkey_accoun").innerHTML=t.message,document.getElementById("main_auth").innerHTML="")})}}getPasskey();
